regoTemplate:
package {{packageName}}

default allow = false

allow {
  input.account.active
  input.account.owner
  input.account.last_review_days <= 90
}

deny[msg] {
  input.account.active
  not input.account.owner
  msg := "{{controlId}}: active account missing owner"
}

deny[msg] {
  input.account.last_review_days > 90
  msg := "{{controlId}}: access review is stale"
}

package {{packageName}}

default allow = false

allow {
  input.logging.enabled
  input.logging.retention_days >= 180
  input.logging.alerting
}

deny[msg] {
  not input.logging.enabled
  msg := "{{controlId}}: logging is disabled"
}

deny[msg] {
  input.logging.retention_days < 180
  msg := "{{controlId}}: log retention is below minimum"
}

package {{packageName}}

default allow = false

allow {
  input.asset.baseline_id
  input.asset.drift_count == 0
}

allow {
  input.asset.baseline_id
  input.asset.approved_exception
}

deny[msg] {
  not input.asset.baseline_id
  msg := "{{controlId}}: asset missing approved baseline"
}

deny[msg] {
  input.asset.drift_count > 0
  not input.asset.approved_exception
  msg := "{{controlId}}: unapproved configuration drift detected"
}
